   105→      if (context) {
   106→        context.watcherActive = true;
   107→      }
   108→    } catch (error: unknown) {
   109→      // AC: @multi-directory-daemon ac-19 - Handle OS limits (EMFILE/ENFILE)
   110→      const code = error instanceof Error && 'code' in error ? (error as NodeJS.ErrnoException).code : undefined;
   111→      if (code === 'EMFILE' || code === 'ENFILE') {
   112→        throw new Error('Unable to watch project - resource limit reached');
   113→      }
   114→      throw error;
   115→    }
   116→  }
   117→
   118→  /**
   119→   * Stop a file watcher for a project.
   120→   *
   121→   * AC: @multi-directory-daemon ac-20, ac-11b
   122→   *
   123→   * @param projectPath - Absolute path to project root
   124→   */
   125→  async stopWatcher(projectPath: string): Promise<void> {
   126→    const normalizedPath = this.normalizePath(projectPath);
   127→    const watcher = this.watchers.get(normalizedPath);
   128→
   129→    if (watcher) {
   130→      await watcher.stop();
   131→      this.watchers.delete(normalizedPath);
   132→
   133→      // Update context
   134→      const context = this.projects.get(normalizedPath);
   135→      if (context) {
   136→        context.watcherActive = false;
   137→      }
   138→    }
   139→  }
   140→
   141→  /**
   142→   * Stop all file watchers.
   143→   *
   144→   * AC: @multi-directory-daemon ac-11b - Shutdown stops all watchers
   145→   */
   146→  async stopAllWatchers(): Promise<void> {
   147→    const stopPromises = Array.from(this.watchers.keys()).map(path =>
   148→      this.stopWatcher(path)
   149→    );
   150→    await Promise.all(stopPromises);
   151→  }
   152→
   153→  /**
   154→   * Register a project for multi-directory daemon support.
   155→   *
   156→   * AC: @multi-directory-daemon ac-4, ac-5, ac-6, ac-7, ac-8, ac-8c
   157→   *
   158→   * Note: This method is synchronous. Start watchers separately via startWatcher().
   159→   *
   160→   * @param projectPath - Absolute path to project root directory
   161→   * @param isDefault - Whether this project should be the default
   162→   * @returns Registered project context
   163→   * @throws Error if path validation fails or .kspec/ not found
   164→   */
   165→  registerProject(projectPath: string, isDefault = false): ProjectContext {
   166→    // AC: @multi-directory-daemon ac-6 - reject relative paths
   167→    if (!this.isAbsolutePath(projectPath)) {
   168→      throw new Error('Path must be absolute');
   169→    }
   170→
   171→    // AC: @multi-directory-daemon ac-7 - reject parent traversal
   172→    if (projectPath.includes('..')) {
   173→      throw new Error('Path must not contain parent traversal');
   174→    }
   175→
   176→    // AC: @multi-directory-daemon ac-8 - normalize path (but don't resolve symlinks)
   177→    const normalizedPath = this.normalizePath(projectPath);
   178→
   179→    // AC: @multi-directory-daemon ac-5 - validate .kspec/ exists
   180→    const kspecDir = join(normalizedPath, '.kspec');
   181→    if (!existsSync(kspecDir)) {
   182→      throw new Error(`Invalid kspec project - .kspec/ not found at ${normalizedPath}`);
   183→    }
   184→
   185→    // AC: @multi-directory-daemon ac-16 - check if already registered (avoid duplicates)
   186→    if (this.projects.has(normalizedPath)) {
   187→      const existing = this.projects.get(normalizedPath)!;
   188→      if (isDefault) {
   189→        this.defaultProjectPath = normalizedPath;
   190→      }
   191→      return existing;
   192→    }
   193→
   194→    // AC: @multi-directory-daemon ac-4 - auto-register and cache
   195→    const context: ProjectContext = {
   196→      path: normalizedPath,
   197→      registeredAt: new Date(),
   198→      watcherActive: false, // Set to true when watcher is started
   199→    };
   200→
   201→    this.projects.set(normalizedPath, context);
   202→
   203→    if (isDefault) {
   204→      this.defaultProjectPath = normalizedPath;
   205→    }
   206→
   207→    return context;
   208→  }
   209→
   210→  /**
   211→   * Get a project by path, or use default project if no path provided.
   212→   *
   213→   * AC: @multi-directory-daemon ac-1, ac-2, ac-3, ac-20b
   214→   *
   215→   * @param projectPath - Optional absolute path to project
   216→   * @returns Project context
   217→   * @throws Error if project not registered, no default, or default invalid
   218→   */
   219→  getProject(projectPath?: string): ProjectContext {
   220→    // AC: @multi-directory-daemon ac-1 - use provided path
   221→    if (projectPath) {
   222→      const normalizedPath = this.normalizePath(projectPath);
   223→      const context = this.projects.get(normalizedPath);
   224→      if (!context) {
   225→        throw new Error(`Project not registered: ${normalizedPath}`);
   226→      }
   227→      return context;
   228→    }
   229→
   230→    // AC: @multi-directory-daemon ac-2, ac-3 - use default or error
   231→    if (!this.defaultProjectPath) {
   232→      throw new Error('No default project configured. Specify X-Kspec-Dir header.');
   233→    }
   234→
   235→    // AC: @multi-directory-daemon ac-20b - check if default project still valid
   236→    const kspecDir = join(this.defaultProjectPath, '.kspec');
   237→    if (!existsSync(kspecDir)) {
   238→      throw new Error('Default project no longer valid. Specify X-Kspec-Dir header.');
   239→    }
   240→
   241→    const context = this.projects.get(this.defaultProjectPath);
   242→    if (!context) {
   243→      throw new Error('Default project not registered');
   244→    }
   245→
   246→    return context;
   247→  }
   248→
   249→  /**
   250→   * Set the default project explicitly.
   251→   *
   252→   * AC: @multi-directory-daemon ac-2
   253→   *
   254→   * @param projectPath - Absolute path to project
   255→   * @throws Error if project not registered
   256→   */
   257→  setDefaultProject(projectPath: string): void {
   258→    const normalizedPath = this.normalizePath(projectPath);
   259→    if (!this.projects.has(normalizedPath)) {
   260→      throw new Error('Project must be registered before setting as default');
   261→    }
   262→    this.defaultProjectPath = normalizedPath;
   263→  }
   264→
   265→  /**
   266→   * Check if a project is registered.
   267→   *
   268→   * @param projectPath - Absolute path to project
   269→   * @returns True if project is registered
   270→   */
   271→  hasProject(projectPath: string): boolean {
   272→    const normalizedPath = this.normalizePath(projectPath);
   273→    return this.projects.has(normalizedPath);
   274→  }
   275→
   276→  /**
   277→   * Unregister a project and stop its watcher.
   278→   *
   279→   * AC: @multi-directory-daemon ac-20
   280→   *
   281→   * @param projectPath - Absolute path to project
   282→   */
   283→  unregisterProject(projectPath: string): void {
   284→    const normalizedPath = this.normalizePath(projectPath);
   285→
   286→    // AC: @multi-directory-daemon ac-20 - Stop watcher when unregistering (async, fire-and-forget)
   287→    void this.stopWatcher(normalizedPath);
   288→
   289→    this.projects.delete(normalizedPath);
   290→
   291→    if (this.defaultProjectPath === normalizedPath) {
   292→      this.defaultProjectPath = null;
   293→    }
   294→  }
   295→
   296→  /**
   297→   * List all registered projects.
   298→   *
   299→   * AC: @multi-directory-daemon ac-14, ac-15
   300→   *
   301→   * @returns Array of registered project contexts
   302→   */
   303→  listProjects(): ProjectContext[] {
   304→    return Array.from(this.projects.values());
   305→  }
   306→
   307→  /**
   308→   * Normalize path without resolving symlinks.
   309→   *
   310→   * AC: @multi-directory-daemon ac-8, ac-8c
   311→   *
   312→   * Normalizes the path by:
   313→   * - Resolving "." segments
   314→   * - Removing trailing slashes
   315→   * - Normalizing multiple slashes
   316→   * - NOT resolving symlinks (symlinked paths treated as separate projects)
   317→   *
   318→   * @param projectPath - Path to normalize
   319→   * @returns Normalized path
   320→   */
   321→  private normalizePath(projectPath: string): string {
   322→    // Remove trailing slashes and resolve "." segments
   323→    // But do NOT resolve symlinks (no realpath/fs.realpathSync)
   324→    let normalized = normalize(projectPath);
   325→
   326→    // Remove trailing slash (normalize doesn't always do this)
   327→    if (normalized !== '/' && normalized.endsWith('/')) {
   328→      normalized = normalized.slice(0, -1);
   329→    }
   330→
   331→    return normalized;
   332→  }
   333→
   334→  /**
   335→   * Check if path is absolute.
   336→   *
   337→   * @param projectPath - Path to check
   338→   * @returns True if path is absolute
   339→   */
   340→  private isAbsolutePath(projectPath: string): boolean {
   341→    return isAbsolute(projectPath);
   342→  }
   343→}
   344→

