        const index = new ReferenceIndex(tasks, items);
        const foundTask = resolveTaskRef(ref, tasks, index);

        // AC: @spec-task-reset ac-2 - Error if already pending
        if (foundTask.status === "pending") {
          error("Task is already pending");
