program
  .name("kspec")
  .description("Kynetic Spec - Structured specification format CLI")
  .version(version)
  // AC: @output-format-option ac-format-json, ac-format-yaml, ac-global-scope
  .option("--format <format>", "Output format (json, yaml)")
  .option("--json", "Output in JSON format (shorthand for --format json)")
  .option("--yaml", "Output in YAML format (shorthand for --format yaml)")
  .option("--raw", "Output in raw JSON format (shorthand for --format json)")
  .option("--debug-shadow", "Enable debug output for shadow operations")
  .hook("preAction", async (thisCommand) => {
    // Skip all hooks during batch dispatch — the batch handler manages modes itself
    if (isBatchMode()) return;

    // Check format options at top level or on subcommand
    const opts = thisCommand.opts();

    // AC: @output-format-option ac-conflict-error
    // Detect conflicting format specifications
    const formatFlags = [];
    if (opts.format) formatFlags.push(`--format ${opts.format}`);
    if (opts.json) formatFlags.push("--json");
    if (opts.yaml) formatFlags.push("--yaml");
    if (opts.raw) formatFlags.push("--raw");

    if (formatFlags.length > 1) {
      console.error(
        chalk.red(`error: Conflicting format options: ${formatFlags.join(", ")}`)
      );
      console.error(chalk.gray("Use only one of: --format <format>, --json, --yaml, --raw"));
      process.exit(EXIT_CODES.ERROR);
    }

    // AC: @output-format-option ac-unsupported-format
    // Validate --format value
    if (opts.format && !VALID_FORMATS.includes(opts.format)) {
      console.error(
        chalk.red(`error: Invalid format '${opts.format}'`)
      );
      console.error(chalk.gray(`Valid formats: ${VALID_FORMATS.join(", ")}`));
      process.exit(EXIT_CODES.ERROR);
    }

    // AC: @output-format-option ac-format-json, ac-format-yaml, ac-json-shorthand, ac-raw-shorthand, ac-yaml-shorthand
    // Set output format based on flags
    if (opts.format) {
      setOutputFormat(opts.format);
    } else if (opts.json || opts.raw) {
      setJsonMode(true);
    } else if (opts.yaml) {
      setYamlMode(true);
    }

    if (opts.debugShadow) {
      setVerboseMode(true);
    }

    // Auto-start daemon if configured and not running
    // Skip for init, serve, and help commands
    const commandName = thisCommand.name();
    const skipCommands = ['init', 'serve', 'help', 'kspec'];

    if (!skipCommands.includes(commandName)) {
      await maybeAutoStartDaemon();
    }
  });

