/**
 * Tests for output format option
 * AC: @output-format-option
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import * as yaml from 'yaml';
import { setupTempFixtures, cleanupTempDir, kspec } from './helpers/cli.js';

describe('Output Format Option', () => {
  let tempDir: string;

  beforeAll(async () => {
    tempDir = await setupTempFixtures();
  });

  afterAll(async () => {
    await cleanupTempDir(tempDir);
  });

  describe('--format json', () => {
    // AC: @output-format-option ac-format-json
    it('produces valid JSON output identical to --json', () => {
      const formatResult = kspec('tasks list --format json', tempDir);
      const jsonResult = kspec('tasks list --json', tempDir);

      expect(formatResult.stdout).toBe(jsonResult.stdout);
      expect(() => JSON.parse(formatResult.stdout)).not.toThrow();
    });

    // AC: @output-format-option ac-format-json
    it('produces valid JSON on task get', () => {
      const result = kspec('task get @01TASK0000F00000000000TASK --format json', tempDir);
      const parsed = JSON.parse(result.stdout);
      expect(parsed._ulid).toBe('01TASK0000F00000000000TASK');
    });
  });

  describe('--format yaml', () => {
    // AC: @output-format-option ac-format-yaml
    it('produces valid YAML output', () => {
      const result = kspec('tasks list --format yaml', tempDir);
      const parsed = yaml.parse(result.stdout);
      expect(Array.isArray(parsed)).toBe(true);
    });

    // AC: @output-format-option ac-format-yaml
    it('contains the same data as --json but in YAML format', () => {
      const jsonResult = kspec('task get @01TASK0000F00000000000TASK --json', tempDir);
      const yamlResult = kspec('task get @01TASK0000F00000000000TASK --yaml', tempDir);

      const jsonParsed = JSON.parse(jsonResult.stdout);
      const yamlParsed = yaml.parse(yamlResult.stdout);

      expect(yamlParsed._ulid).toBe(jsonParsed._ulid);
      expect(yamlParsed.title).toBe(jsonParsed.title);
      expect(yamlParsed.status).toBe(jsonParsed.status);
    });

    // AC: @output-format-option ac-yaml-no-ansi
    it('contains no ANSI escape codes', () => {
      const result = kspec('tasks list --format yaml', tempDir);
      // ANSI escape codes start with \x1b[ or \033[
      expect(result.stdout).not.toMatch(/\x1b\[/);
      expect(result.stdout).not.toMatch(/\033\[/);
    });

    // AC: @output-format-option ac-yaml-references
    it('includes @ prefix in reference fields', () => {
      const result = kspec('task get @01TASK0000F00000000000TASK --yaml', tempDir);
      const parsed = yaml.parse(result.stdout);
      // The task in fixtures has a spec_ref
      if (parsed.spec_ref) {
        expect(parsed.spec_ref).toMatch(/^@/);
      }
    });
  });

  describe('--json shorthand', () => {
    // AC: @output-format-option ac-json-shorthand
    it('is equivalent to --format json (backward compatible)', () => {
      const shorthandResult = kspec('tasks list --json', tempDir);
      const explicitResult = kspec('tasks list --format json', tempDir);

      expect(shorthandResult.stdout).toBe(explicitResult.stdout);
      expect(() => JSON.parse(shorthandResult.stdout)).not.toThrow();
    });
  });

  describe('--raw shorthand', () => {
    // AC: @output-format-option ac-raw-shorthand
    it('is equivalent to --format json', () => {
      const rawResult = kspec('tasks list --raw', tempDir);
      const jsonResult = kspec('tasks list --json', tempDir);

      expect(rawResult.stdout).toBe(jsonResult.stdout);
      expect(() => JSON.parse(rawResult.stdout)).not.toThrow();
    });
  });

  describe('--yaml shorthand', () => {
    // AC: @output-format-option ac-yaml-shorthand
    it('is equivalent to --format yaml', () => {
      const shorthandResult = kspec('tasks list --yaml', tempDir);
      const explicitResult = kspec('tasks list --format yaml', tempDir);

      expect(shorthandResult.stdout).toBe(explicitResult.stdout);
      expect(() => yaml.parse(shorthandResult.stdout)).not.toThrow();
    });
  });

  describe('conflict detection', () => {
    // AC: @output-format-option ac-conflict-error
    it('errors when --json and --yaml are both provided', () => {
      const result = kspec('tasks list --json --yaml', tempDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/Conflicting format options/);
      expect(result.stderr).toMatch(/--json/);
      expect(result.stderr).toMatch(/--yaml/);
    });

    // AC: @output-format-option ac-conflict-error
    it('errors when --format and --json are both provided', () => {
      const result = kspec('tasks list --format yaml --json', tempDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/Conflicting format options/);
    });

    // AC: @output-format-option ac-conflict-error
    it('errors when --raw and --yaml are both provided', () => {
      const result = kspec('tasks list --raw --yaml', tempDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/Conflicting format options/);
    });

    // AC: @output-format-option ac-conflict-error
    it('errors when --format and --raw are both provided', () => {
      const result = kspec('tasks list --format json --raw', tempDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/Conflicting format options/);
    });
  });

  describe('invalid format', () => {
    // AC: @output-format-option ac-unsupported-format
    it('errors on invalid format value', () => {
      const result = kspec('tasks list --format csv', tempDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/Invalid format 'csv'/);
      expect(result.stderr).toMatch(/Valid formats: json, yaml/);
    });

    // AC: @output-format-option ac-unsupported-format
    it('errors on unknown format value', () => {
      const result = kspec('tasks list --format xml', tempDir, { expectFail: true });
      expect(result.exitCode).not.toBe(0);
      expect(result.stderr).toMatch(/Invalid format 'xml'/);
    });
  });

  describe('global scope', () => {
    // AC: @output-format-option ac-global-scope
    it('--yaml works on item list', () => {
      const result = kspec('item list --yaml', tempDir);
      expect(result.exitCode).toBe(0);
      expect(() => yaml.parse(result.stdout)).not.toThrow();
    });

    // AC: @output-format-option ac-global-scope
    it('--raw works on tasks ready', () => {
      const result = kspec('tasks ready --raw', tempDir);
      expect(result.exitCode).toBe(0);
      expect(() => JSON.parse(result.stdout)).not.toThrow();
    });

    // AC: @output-format-option ac-global-scope
    it('--format yaml works on session start', () => {
      const result = kspec('session start --format yaml', tempDir);
      expect(result.exitCode).toBe(0);
      // Session start outputs YAML context
      expect(() => yaml.parse(result.stdout)).not.toThrow();
    });
  });
});

