    if (opts.yaml) formatFlags.push("--yaml");
    if (opts.raw) formatFlags.push("--raw");

    if (formatFlags.length > 1) {
      console.error(
        chalk.red(`error: Conflicting format options: ${formatFlags.join(", ")}`)
