          process.exit(EXIT_CODES.ERROR);
        }

        const metaCtx = await loadMetaContext(ctx);
        let observations = metaCtx.observations || [];

        // Apply filters
        if (options.type) {
          observations = observations.filter(
            (obs) => obs.type === options.type,
