          }
        }

        // Search in conventions
        if (!found) {
          const conventions = metaCtx.manifest?.conventions || [];
          const convention = conventions.find(
            (c) =>
              c.domain === normalizedRef || c._ulid.startsWith(normalizedRef),
          );
          if (convention) {
            found = convention;
            itemType = "convention";
          }
        }

        if (!found || !itemType) {
          error(errors.reference.metaNotFound(ref));
          process.exit(EXIT_CODES.ERROR);
        }

        // Update fields based on type
        if (itemType === "agent") {
          const item = found as Agent;
          if (options.name) item.name = options.name;
          if (options.description !== undefined)
            item.description = options.description;
          if (options.addCapability) {
            if (!item.capabilities.includes(options.addCapability)) {
              item.capabilities.push(options.addCapability);
            }
          }
          if (options.addTool) {
            if (!item.tools.includes(options.addTool)) {
              item.tools.push(options.addTool);
            }
          }
          if (options.addConvention) {
            if (!item.conventions.includes(options.addConvention)) {
              item.conventions.push(options.addConvention);
            }
          }
        } else if (itemType === "workflow") {
          const item = found as Workflow;
          if (options.trigger) item.trigger = options.trigger;
          if (options.description !== undefined)
            item.description = options.description;
        } else {
          const item = found as Convention;
          // Convention doesn't have a description field
          if (options.addRule) {
            if (!item.rules.includes(options.addRule)) {
              item.rules.push(options.addRule);
            }
          }
        }

        // Save the updated item
        await saveMetaItem(ctx, found, itemType);

        // AC: @trait-shadow-commit ac-1
        await commitIfShadow(
          ctx.shadow,
          `meta-set-${itemType}`,
          found._ulid.substring(0, 8),
        );

        if (isJsonMode()) {
          // In JSON mode, output the item data directly
          console.log(JSON.stringify(found, null, 2));
        } else {
          const idOrDomain =
            itemType === "agent"
              ? (found as Agent).id
              : itemType === "workflow"
                ? (found as Workflow).id
                : (found as Convention).domain;
          success(`Updated ${itemType}: ${idOrDomain}`);
        }
      } catch (err) {
        error(errors.failures.updateMetaItem, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // Meta delete command - delete meta items
  markMutating(meta.command("delete <ref>"))
    .description("Delete a meta item")
    .option("--confirm", "Skip confirmation prompt")
    .action(async (ref: string, options) => {
      try {
        const ctx = await initContext();
        const metaCtx = await loadMetaContext(ctx);

        // Find the item to determine type
        const normalizedRef = ref.startsWith("@") ? ref.substring(1) : ref;
        let itemType:
          | "agent"
          | "workflow"
          | "convention"
          | "observation"
          | null = null;
        let itemUlid: string | null = null;
        let itemLabel: string | null = null;

        // Search in agents
        const agents = metaCtx.manifest?.agents || [];
        const agent = agents.find(
          (a) => a.id === normalizedRef || a._ulid.startsWith(normalizedRef),
        );
        if (agent) {
          itemType = "agent";
          itemUlid = agent._ulid;
          itemLabel = `agent ${agent.id}`;
        }

        // Search in workflows
        if (!itemType) {
          const workflows = metaCtx.manifest?.workflows || [];
          const workflow = workflows.find(
            (w) => w.id === normalizedRef || w._ulid.startsWith(normalizedRef),
          );
          if (workflow) {
            itemType = "workflow";
            itemUlid = workflow._ulid;
            itemLabel = `workflow ${workflow.id}`;
          }
        }

        // Search in conventions
        if (!itemType) {
          const conventions = metaCtx.manifest?.conventions || [];
          const convention = conventions.find(
            (c) =>
              c.domain === normalizedRef || c._ulid.startsWith(normalizedRef),
          );
          if (convention) {
            itemType = "convention";
            itemUlid = convention._ulid;
            itemLabel = `convention ${convention.domain}`;
          }
        }

        // Search in observations
        if (!itemType) {
          const observations = metaCtx.observations || [];
          const observation = observations.find((o) =>
            o._ulid.startsWith(normalizedRef),
          );
          if (observation) {
            itemType = "observation";
            itemUlid = observation._ulid;
            itemLabel = `observation ${observation._ulid.substring(0, 8)}`;
          }
        }

        if (!itemType || !itemUlid || !itemLabel) {
          error(errors.reference.metaNotFound(ref));
          process.exit(EXIT_CODES.ERROR);
        }

        // Check for dangling references (unless --confirm is used to override)
        if (!options.confirm) {
          // Check tasks with meta_ref
          const tasks = await loadAllTasks(ctx);
          const referencingTasks = tasks.filter((t) => {
            if (!t.meta_ref) return false;
            // Resolve the task's meta_ref to a ULID
            const taskMetaRef = resolveMetaRefToUlid(t.meta_ref, metaCtx);
            // Compare ULIDs to handle both semantic IDs and ULID prefixes
            return taskMetaRef && taskMetaRef.ulid === itemUlid;
          });

          if (referencingTasks.length > 0) {
            const taskRefs = referencingTasks
              .map((t) => `@${t.slugs?.[0] || t._ulid.substring(0, 8)}`)
              .join(", ");
            error(
              errors.operation.cannotDeleteReferencedByTasks(
                itemLabel,
                referencingTasks.length,
                taskRefs,
              ),
            );
            process.exit(EXIT_CODES.ERROR);
          }

          // Check observations with workflow_ref (only for workflows)
          if (itemType === "workflow") {
            const observations = metaCtx.observations || [];
            const referencingObservations = observations.filter((o) => {
              if (!o.workflow_ref) return false;
              // Resolve the observation's workflow_ref to a ULID
              const obsWorkflowRef = resolveMetaRefToUlid(
                o.workflow_ref,
                metaCtx,
              );
              // Compare ULIDs to handle both semantic IDs and ULID prefixes
              return obsWorkflowRef && obsWorkflowRef.ulid === itemUlid;
            });

            if (referencingObservations.length > 0) {
              const obsRefs = referencingObservations
                .map((o) => `@${o._ulid.substring(0, 8)}`)
                .join(", ");
              error(
                errors.operation.cannotDeleteReferencedByObservations(
                  itemLabel,
                  referencingObservations.length,
                  obsRefs,
                ),
              );
              process.exit(EXIT_CODES.ERROR);
            }
          }

          // Show confirmation prompt even if no references found
          error(errors.operation.confirmRequired(itemLabel));
          process.exit(EXIT_CODES.ERROR);
        }

        // Delete the item
        const deleted = await deleteMetaItem(ctx, itemUlid, itemType);

        if (!deleted) {
          error(errors.operation.deleteItemFailed(itemLabel));
          process.exit(EXIT_CODES.ERROR);
        }

        // AC: @trait-shadow-commit ac-1
        await commitIfShadow(
          ctx.shadow,
          `meta-delete-${itemType}`,
          itemUlid.substring(0, 8),
        );

        success(`Deleted ${itemLabel}`);
      } catch (err) {
        error(errors.failures.deleteMetaItem, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // meta-focus-cmd: kspec meta focus [ref]
  markMutating(meta.command("focus [ref]"))
    .description("Get or set session focus")
    .option("--clear", "Clear current focus")
    .action(async (ref: string | undefined, options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const sessionCtx = await loadSessionContext(ctx);

        // Clear focus
        if (options.clear) {
          sessionCtx.focus = null;
          await saveSessionContext(ctx, sessionCtx);

          output({ focus: null }, () => success("Cleared session focus"));
          return;
        }

        // Show current focus
        if (!ref) {
          output({ focus: sessionCtx.focus }, () => {
            if (sessionCtx.focus) {
              console.log(`Current focus: ${sessionCtx.focus}`);
            } else {
              console.log(chalk.yellow("No focus set"));
            }
          });
          return;
        }

        // Set focus to ref
        sessionCtx.focus = ref.startsWith("@") ? ref : `@${ref}`;
        await saveSessionContext(ctx, sessionCtx);

        output({ focus: sessionCtx.focus }, () =>
          success(`Set focus to: ${sessionCtx.focus}`),
        );
      } catch (err) {
        error(errors.failures.updateSessionContext, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // meta-thread-cmd: kspec meta thread <action> [text]
  markMutating(meta.command("thread <action> [text]"))
    .description("Manage active threads")
    .action(async (action: string, text: string | undefined) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const sessionCtx = await loadSessionContext(ctx);

        // List threads
        if (action === "list") {
          output({ threads: sessionCtx.threads }, () => {
            if (sessionCtx.threads.length === 0) {
              console.log(chalk.yellow("No active threads"));
            } else {
              console.log("Active threads:");
              sessionCtx.threads.forEach((thread, idx) => {
                console.log(`  ${idx + 1}. ${thread}`);
              });
            }
          });
          return;
        }

        // Clear all threads
        if (action === "clear") {
          sessionCtx.threads = [];
          await saveSessionContext(ctx, sessionCtx);

          output({ threads: [] }, () => success("Cleared all threads"));
          return;
        }

        // Add thread
        if (action === "add") {
          if (!text) {
            error("Thread text is required for add action");
            process.exit(EXIT_CODES.ERROR);
          }

          sessionCtx.threads.push(text);
          await saveSessionContext(ctx, sessionCtx);

          output({ threads: sessionCtx.threads, added: text }, () =>
            success(`Added thread: ${text}`),
          );
          return;
        }

        // Remove thread by index (1-based)
        if (action === "remove") {
          if (!text) {
            error("Index is required for remove action");
            process.exit(EXIT_CODES.ERROR);
          }

          const index = parseInt(text, 10);
          if (
            Number.isNaN(index) ||
            index < 1 ||
            index > sessionCtx.threads.length
          ) {
            error(
              `Invalid index: ${text}. Must be between 1 and ${sessionCtx.threads.length}`,
            );
            process.exit(EXIT_CODES.ERROR);
          }

          const removed = sessionCtx.threads.splice(index - 1, 1)[0];
          await saveSessionContext(ctx, sessionCtx);

          output({ threads: sessionCtx.threads, removed }, () =>
            success(`Removed thread: ${removed}`),
          );
          return;
        }

        // Unknown action
        error(`Unknown action: ${action}. Use add, remove, list, or clear`);
        process.exit(EXIT_CODES.ERROR);
      } catch (err) {
        error(errors.failures.updateSessionContext, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // meta-question-cmd: kspec meta question <action> [text]
  markMutating(meta.command("question <action> [text]"))
    .description("Manage open questions")
    .action(async (action: string, text: string | undefined) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const sessionCtx = await loadSessionContext(ctx);

        // List questions
        if (action === "list") {
          output({ questions: sessionCtx.open_questions }, () => {
            if (sessionCtx.open_questions.length === 0) {
              console.log(chalk.yellow("No open questions"));
            } else {
              console.log("Open questions:");
              sessionCtx.open_questions.forEach((question, idx) => {
                console.log(`  ${idx + 1}. ${question}`);
              });
            }
          });
          return;
        }

        // Clear all questions
        if (action === "clear") {
          sessionCtx.open_questions = [];
          await saveSessionContext(ctx, sessionCtx);

          output({ questions: [] }, () => success("Cleared all questions"));
          return;
        }

        // Add question
        if (action === "add") {
          if (!text) {
            error("Question text is required for add action");
            process.exit(EXIT_CODES.ERROR);
          }

          sessionCtx.open_questions.push(text);
          await saveSessionContext(ctx, sessionCtx);

          output({ questions: sessionCtx.open_questions, added: text }, () =>
            success(`Added question: ${text}`),
          );
          return;
        }

        // Remove question by index (1-based)
        if (action === "remove") {
          if (!text) {
            error("Index is required for remove action");
            process.exit(EXIT_CODES.ERROR);
          }

          const index = parseInt(text, 10);
          if (
            Number.isNaN(index) ||
            index < 1 ||
            index > sessionCtx.open_questions.length
          ) {
            error(
              `Invalid index: ${text}. Must be between 1 and ${sessionCtx.open_questions.length}`,
            );
            process.exit(EXIT_CODES.ERROR);
          }

          const removed = sessionCtx.open_questions.splice(index - 1, 1)[0];
          await saveSessionContext(ctx, sessionCtx);

          output({ questions: sessionCtx.open_questions, removed }, () =>
            success(`Removed question: ${removed}`),
          );
          return;
        }

        // Unknown action
        error(`Unknown action: ${action}. Use add, remove, list, or clear`);
        process.exit(EXIT_CODES.ERROR);
      } catch (err) {
        error(errors.failures.updateSessionContext, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // meta-context-cmd: kspec meta context
  meta
    .command("context")
    .description("Show full session context")
    .option("--clear", "Clear all session context")
    .action(async (options) => {
      try {
        const ctx = await initContext();

        if (!ctx.manifestPath) {
          error(errors.project.noKspecProject);
          process.exit(EXIT_CODES.ERROR);
        }

        const sessionCtx = await loadSessionContext(ctx);

        // Clear all context
        if (options.clear) {
          sessionCtx.focus = null;
          sessionCtx.threads = [];
          sessionCtx.open_questions = [];
          await saveSessionContext(ctx, sessionCtx);

          output(
            {
              focus: null,
              threads: [],
              open_questions: [],
              updated_at: sessionCtx.updated_at,
            },
            () => success("Cleared all session context"),
          );
          return;
        }

        // Show full session context
        output(
          {
            focus: sessionCtx.focus,
            threads: sessionCtx.threads,
            open_questions: sessionCtx.open_questions,
            updated_at: sessionCtx.updated_at,
          },
          () => {
            console.log(chalk.bold("Session Context"));
            console.log(chalk.gray("─".repeat(60)));

            // Focus
            console.log(chalk.bold("\nFocus:"));
            if (sessionCtx.focus) {
              console.log(`  ${sessionCtx.focus}`);
            } else {
              console.log(chalk.gray("  (none)"));
            }

            // Active threads
            console.log(chalk.bold("\nActive Threads:"));
            if (sessionCtx.threads.length > 0) {
              sessionCtx.threads.forEach((thread, idx) => {
                console.log(`  ${idx + 1}. ${thread}`);
              });
            } else {
              console.log(chalk.gray("  (none)"));
            }

            // Open questions
            console.log(chalk.bold("\nOpen Questions:"));
            if (sessionCtx.open_questions.length > 0) {
              sessionCtx.open_questions.forEach((question, idx) => {
                console.log(`  ${idx + 1}. ${question}`);
              });
            } else {
              console.log(chalk.gray("  (none)"));
            }

            // Last updated
            console.log(chalk.bold("\nLast Updated:"));
            const updatedDate = new Date(sessionCtx.updated_at);
            console.log(`  ${updatedDate.toISOString()}`);
            console.log(chalk.gray(`  (${updatedDate.toLocaleString()})`));
          },
        );
      } catch (err) {
        error(errors.failures.updateSessionContext, err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

import chalk from "chalk";
import type { Command } from "commander";
import {
  buildIndexes,
  initContext,
  loadInboxItems,
  loadMetaContext,
} from "../../parser/index.js";
import type {
  LoadedAgent,
  LoadedConvention,
  LoadedObservation,
  LoadedWorkflow,
} from "../../parser/meta.js";
import type {
  LoadedInboxItem,
  LoadedSpecItem,
  LoadedTask,
} from "../../parser/yaml.js";
import { errors } from "../../strings/index.js";
import { formatMatchedFields, grepItem } from "../../utils/grep.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, output } from "../output.js";

/**
 * Format a spec item for search results
 */
function formatSearchItem(item: LoadedSpecItem, matchedFields: string[]): void {
  const shortId = item._ulid.slice(0, 8);
  const slugStr = item.slugs.length > 0 ? chalk.cyan(`@${item.slugs[0]}`) : "";
  const typeStr = chalk.gray(`[${item.type}]`);

  let status = "";
  if (item.status && typeof item.status === "object") {
    const s = item.status as { maturity?: string; implementation?: string };
    if (s.implementation) {
      const implColor =
        s.implementation === "verified"
          ? chalk.green
          : s.implementation === "implemented"
            ? chalk.cyan
            : s.implementation === "in_progress"
              ? chalk.yellow
              : chalk.gray;
      status = implColor(s.implementation);
    }
  }

  let line = `${chalk.gray(shortId)} ${typeStr} ${item.title}`;
  if (slugStr) line += ` ${slugStr}`;
  if (status) line += ` ${status}`;

  console.log(line);
  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
}

/**
 * Format a task for search results
 */
function formatSearchTask(task: LoadedTask, matchedFields: string[]): void {
  const shortId = task._ulid.slice(0, 8);
  const slugStr = task.slugs.length > 0 ? chalk.cyan(`@${task.slugs[0]}`) : "";

  const statusColor =
    task.status === "completed"
      ? chalk.green
      : task.status === "in_progress"
        ? chalk.blue
        : task.status === "blocked"
          ? chalk.red
          : chalk.gray;

  const priority =
    task.priority <= 2
      ? chalk.red(`P${task.priority}`)
      : chalk.gray(`P${task.priority}`);

  let line = `${chalk.gray(shortId)} ${statusColor(`[${task.status}]`)} ${priority} ${task.title}`;
  if (slugStr) line += ` ${slugStr}`;

  console.log(line);
  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
}

/**
 * Format an inbox item for search results
 */
function formatSearchInbox(item: LoadedInboxItem, matchedFields: string[]): void {
  const shortId = item._ulid.slice(0, 8);
  const typeStr = chalk.gray("[inbox]");

  // Truncate text if too long
  const displayText =
    item.text.length > 60 ? `${item.text.substring(0, 57)}...` : item.text;

  const line = `${chalk.gray(shortId)} ${typeStr} ${displayText}`;

  console.log(line);
  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
}

/**
 * Format a meta entity for search results
 */
function formatSearchMeta(
  entity: LoadedObservation | LoadedAgent | LoadedWorkflow | LoadedConvention,
  entityType: "observation" | "agent" | "workflow" | "convention",
  matchedFields: string[],
): void {
  const shortId = entity._ulid.slice(0, 8);
  const typeStr = chalk.gray(`[${entityType}]`);

  let displayText = "";
  if (entityType === "observation") {
    const obs = entity as LoadedObservation;
    displayText =
      obs.content.length > 60
        ? `${obs.content.substring(0, 57)}...`
        : obs.content;
  } else if (entityType === "agent") {
    const agent = entity as LoadedAgent;
    displayText = `${agent.id} - ${agent.name}`;
  } else if (entityType === "workflow") {
    const workflow = entity as LoadedWorkflow;
    displayText = `${workflow.id}${workflow.description ? ` - ${workflow.description}` : ""}`;
  } else if (entityType === "convention") {
    const convention = entity as LoadedConvention;
    const rulePreview = convention.rules.length > 0 ? ` - ${convention.rules[0]}` : "";
    displayText = `${convention.domain}${rulePreview}`;
  }

  const line = `${chalk.gray(shortId)} ${typeStr} ${displayText}`;

  console.log(line);
  console.log(chalk.gray(`  matched: ${formatMatchedFields(matchedFields)}`));
}

interface SearchResult {
  type: "item" | "task" | "inbox" | "observation" | "agent" | "workflow" | "convention";
  item: LoadedSpecItem | LoadedTask | LoadedInboxItem | LoadedObservation | LoadedAgent | LoadedWorkflow | LoadedConvention;
  matchedFields: string[];
}

/**
 * Register the search command
 */
export function registerSearchCommand(program: Command): void {
  program
    .command("search <pattern>")
    .description("Search across items, tasks, inbox, and meta entities with regex pattern")
    .option("-t, --type <type>", "Filter by item type")
    .option("-s, --status <status>", "Filter by task status")
    .option("--items-only", "Search only spec items")
    .option("--tasks-only", "Search only tasks")
    .option("--limit <n>", "Limit results", "50")
    .action(async (pattern, options) => {
      try {
        const ctx = await initContext();
        const { itemIndex, tasks, items, refIndex } = await buildIndexes(ctx);

        const results: SearchResult[] = [];
        const limit = parseInt(options.limit, 10) || 50;

        // Search spec items
        if (!options.tasksOnly) {
          for (const item of items) {
            // Apply type filter
            if (options.type && item.type !== options.type) continue;

            const match = grepItem(
              item as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "item",
                item,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Search tasks
        if (!options.itemsOnly) {
          for (const task of tasks) {
            // Apply status filter
            if (options.status && task.status !== options.status) continue;

            const match = grepItem(
              task as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "task",
                item: task,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Search inbox items (AC-7)
        if (!options.itemsOnly && !options.tasksOnly) {
          const inboxItems = await loadInboxItems(ctx);
          for (const inboxItem of inboxItems) {
            const match = grepItem(
              inboxItem as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "inbox",
                item: inboxItem,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Search meta entities (AC-7)
        if (!options.itemsOnly && !options.tasksOnly) {
          const metaCtx = await loadMetaContext(ctx);

          // Search observations
          for (const observation of metaCtx.observations) {
            const match = grepItem(
              observation as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "observation",
                item: observation,
                matchedFields: match.matchedFields,
              });
            }
          }

          // Search agents
          for (const agent of metaCtx.agents) {
            const match = grepItem(
              agent as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "agent",
                item: agent,
                matchedFields: match.matchedFields,
              });
            }
          }

          // Search workflows
          for (const workflow of metaCtx.workflows) {
            const match = grepItem(
              workflow as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "workflow",
                item: workflow,
                matchedFields: match.matchedFields,
              });
            }
          }

          // Search conventions
          for (const convention of metaCtx.conventions) {
            const match = grepItem(
              convention as unknown as Record<string, unknown>,
              pattern,
            );
            if (match) {
              results.push({
                type: "convention",
                item: convention,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Limit results
        const limitedResults = results.slice(0, limit);

        output(
          {
            pattern,
            results: limitedResults.map((r) => {
              // Get title/display text based on entity type
              let title = "";
