              pattern,
            );
            if (match) {
              results.push({
                type: "convention",
                item: convention,
                matchedFields: match.matchedFields,
              });
            }
          }
        }

        // Limit results
        const limitedResults = results.slice(0, limit);

        output(
          {
            pattern,
            results: limitedResults.map((r) => {
              // Get title/display text based on entity type
              let title = "";
              if (r.type === "item" || r.type === "task") {
